// Generated by philote from page /bookings. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { must } from "@/lib/backend";
import { readBookingCard } from "@/lib/reads";
import { needViewer } from "@/lib/viewer";

import BookingCard from "@/components/common/booking-card";

export const metadata: Metadata = { title: "Bookings" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <h1 className="mx-auto w-full max-w-5xl px-4 pt-8 font-heading text-3xl font-semibold tracking-tight sm:px-6">{"Bookings"}</h1>
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    // proxy.ts already sent a visitor without a viewer to pick one; this
    // catches one whose viewer is gone.
    const viewer = await needViewer();
    const loaded = await must(api.bookingsOf(viewer.id));
    const props1 = await Promise.all(loaded.map(readBookingCard));
    return (
        <>
            {props1.length === 0 ? (
                <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"Nothing booked yet."}</p>
            ) : (
                <section className="mx-auto grid w-full max-w-5xl gap-6 px-4 pt-4 pb-8 sm:grid-cols-2 sm:px-6 lg:grid-cols-3 has-[>[data-shape=row]]:max-w-3xl has-[>[data-shape=row]]:grid-cols-1 has-[>[data-shape=row]]:gap-4">
                    {props1.map((item) => (
                        <BookingCard key={item.booking.id} {...item} />
                    ))}
                </section>
            )}
        </>
    );
}
